305	  const handleFormSubmission = async (data: MedicationOrderFormData) => {
306	    // A same-day selection resolves to no scheduledDate (the posting layer supplies the datetime);
307	    // an explicit future/past day is kept.
308	    const now = new Date();
309	    const scheduledDate = getOrderStartDateForSubmission(data.scheduledDate, startDateMin);
310	
311	    if (
312	      isFutureRevisionOfActiveMedication(
313	        initialOrderBasketItem?.action,
314	        scheduledDate,
315	        initialOrderBasketItem?.scheduledDate,
316	        now,
317	      )
318	    ) {
319	      setError('scheduledDate', {
320	        type: 'manual',
321	        message: t(
322	          'activeMedicationRevisionCannotStartInFuture',
323	          'Revisions to an active medication must start today or earlier.',
324	        ),
325	      });
326	      return;
327	    }
328	
329	    const newBasketItem = {
330	      ...initialOrderBasketItem,
331	      drug: data.drug,
332	      isFreeTextDosage: data.isFreeTextDosage,
333	      freeTextDosage: data.isFreeTextDosage ? data.freeTextDosage : null,
334	      dosage: data.isFreeTextDosage ? null : data.dosage,
335	      unit: data.isFreeTextDosage ? null : data.unit,
336	      route: data.isFreeTextDosage ? null : data.route,
337	      patientInstructions: data.isFreeTextDosage ? null : data.patientInstructions,
338	      asNeeded: data.asNeeded,
339	      asNeededCondition: data.asNeededCondition,
340	      duration: data.duration,
341	      durationUnit: data.durationUnit,
342	      pillsDispensed: data.pillsDispensed,
343	      isQuantityManual: isManualOverride,
344	      quantityUnits: data.quantityUnits,
345	      numRefills: data.numRefills,
346	      indication: data.indication,
347	      frequency: data.isFreeTextDosage ? null : data.frequency,
348	      scheduledDate,
349	      action: initialOrderBasketItem?.action ?? 'NEW',
350	      commonMedicationName: data.drug.display,
351	      display: data.drug.display,
352	      visit: initialOrderBasketItem?.visit ?? visitContext, // TODO: they really should be the same
353	    } as DrugOrderBasketItem;
354	
355	    try {
